export default {"client":"import {createMeditationTimer} from '/practice/timer-model.js';\nimport {createPracticeAudio} from '/practice/audio-engine.js';\nconst $=id=>document.getElementById(id),timer=createMeditationTimer();let audio=createPracticeAudio(),audioGeneration=0,tick=null;let previousState='idle',lastInterval=0,cueReady=false,selectedMinutes=20,startGeneration=0,starting=false,soundWasPlaying=false;\nconst say=(text,id='practice-status')=>{$(id).textContent=text;if(id==='practice-status'&&$('timer-panel').hidden)$('sound-status').textContent=text};\nfunction stopSound(){audio.stop();soundWasPlaying=false;$('sound-state').textContent='声音已停止';$('play-sound').textContent='播放声音'}\nfunction config(){timer.configure({minutes:$('duration').value,preparationSeconds:$('preparation').value,intervalMinutes:$('interval').value})}\nfunction render(){if(starting)return;const playing=audio.status().playing===true;if(soundWasPlaying&&!playing){$('sound-state').textContent='声音已结束';$('play-sound').textContent='播放声音'}soundWasPlaying=playing;const s=timer.snapshot();const seconds=Math.ceil(s.phaseRemainingMs/1000),min=Math.floor(seconds/60),sec=seconds%60;const display=String(min).padStart(2,'0')+':'+String(sec).padStart(2,'0');if($('clock').textContent!==display)$('clock').textContent=display;$('phase').textContent=s.state==='idle'?'准备好，再开始':s.state==='paused'?'已暂停':s.phase==='preparation'?'准备入坐':s.state==='finished'?'本次练习已结束':'安住当下';$('timer-progress').value=s.progress;$('start').hidden=!['idle','finished'].includes(s.state);$('pause').hidden=s.state!=='running';$('resume').hidden=s.state!=='paused';$('end').hidden=!['running','paused'].includes(s.state);for(const e of document.querySelectorAll('[data-timer-config]'))e.disabled=['running','paused'].includes(s.state);if(s.state==='running'&&s.phase==='meditation'&&s.intervalsCompleted>lastInterval){lastInterval=s.intervalsCompleted;if($('bell-enabled').checked&&cueReady&&!document.hidden)audio.bell()}\n if(s.state==='finished'&&previousState!=='finished'){stopSound();let completion='计时完成。可以留意呼吸与身体此刻的感受。';if($('bell-enabled').checked&&cueReady&&!document.hidden&&!audio.bell())completion='计时完成；浏览器未允许提示音。';say(completion);}\n previousState=s.state;\n}\n$('start').onclick=async()=>{if(starting)return;const attempt=++startGeneration;starting=true;$('start').disabled=true;$('end').hidden=false;$('end').textContent='取消开始';for(const e of document.querySelectorAll('[data-timer-config]'))e.disabled=true;try{config();cueReady=false;if($('bell-enabled').checked){try{await audio.prepare();if(attempt!==startGeneration)return;cueReady=true}catch{if(attempt===startGeneration)say('提示音暂不可用，仍可使用静默计时。')}}if(attempt!==startGeneration)return;lastInterval=0;timer.start();say('计时已开始。后台或锁屏时，网页提示音可能延迟或无法播放。');render()}catch(e){if(attempt===startGeneration)say(e.message)}finally{if(attempt===startGeneration){starting=false;$('start').disabled=false;$('end').textContent='结束本次';render()}}};\n$('pause').onclick=()=>{timer.pause();stopSound();say('已暂停计时与声景。');render()};$('resume').onclick=()=>{timer.resume();say('计时已继续；声景需手动播放。');render()};$('end').onclick=()=>{startGeneration++;starting=false;$('start').disabled=false;$('end').textContent='结束本次';timer.finish();stopSound();cueReady=false;say('本次计时已结束。');render()};\nfor(const b of document.querySelectorAll('[data-minutes]'))b.onclick=()=>{selectedMinutes=Number(b.dataset.minutes);$('duration').value=selectedMinutes;for(const other of document.querySelectorAll('[data-minutes]'))other.setAttribute('aria-pressed',String(other===b));config();render()};\n$('duration').oninput=()=>{for(const b of document.querySelectorAll('[data-minutes]'))b.setAttribute('aria-pressed',String(Number(b.dataset.minutes)===Number($('duration').value)));try{config();render()}catch{}};for(const id of ['preparation','interval'])$(id).onchange=()=>{try{config();render()}catch(e){say(e.message)}};\n$('play-sound').onclick=async()=>{const engine=audio,attempt=audioGeneration;try{if(await engine.play($('sound').value)&&attempt===audioGeneration){cueReady=$('bell-enabled').checked&&engine.status().ready;soundWasPlaying=engine.status().playing===true;$('sound-state').textContent=$('sound').selectedOptions[0].textContent+' · 正在试听';$('play-sound').textContent='重新播放';say('从舒适低音量开始；不适时请立即停止。','sound-status')}}catch(e){if(attempt===audioGeneration)say(e.message||'浏览器无法播放音频。','sound-status')}};\n$('stop-sound').onclick=stopSound;$('volume').oninput=()=>{audio.setVolume(Number($('volume').value)/100);$('volume-value').textContent=$('volume').value+'%'};$('mute').onclick=()=>{const muted=!audio.status().muted;audio.setMuted(muted);$('mute').setAttribute('aria-pressed',String(muted));$('mute').textContent=muted?'取消静音':'静音'};\n$('sound').onchange=()=>{stopSound();say('已切换声音类型，请点击播放。','sound-status')};\nfor(const b of document.querySelectorAll('button[data-theme]'))b.onclick=()=>{document.body.dataset.theme=b.dataset.theme;for(const x of document.querySelectorAll('button[data-theme]'))x.setAttribute('aria-pressed',String(x===b))};\nfunction view(name,push=false){document.body.dataset.view=name;const sound=name==='sounds';$('timer-panel').hidden=sound;$('reflection').hidden=!sound;for(const a of document.querySelectorAll('[data-view]')){if(a.dataset.view===name)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')}if(push)history.pushState({view:name},'','/practice/'+name);$('app-heading').textContent=sound?'听见声音，觉察当下。':'留一段时间，安静坐下。'}\nfor(const a of document.querySelectorAll('[data-view]'))a.onclick=e=>{e.preventDefault();view(a.dataset.view,true)};window.addEventListener('popstate',()=>view(location.pathname.endsWith('/sounds')?'sounds':'timer'));\n$('clear-reflection').onclick=()=>{$('reflection-note').value='';say('本页觉察文字已清除。','reflection-status')};\nfunction cancelPending(){startGeneration++;audioGeneration++;starting=false;$('start').disabled=false;$('end').textContent='结束本次';}\nfunction renderSilently(){const current=timer.snapshot();lastInterval=current.intervalsCompleted;previousState=current.state;render();return current;}\nfunction startTick(){if(tick!==null)clearInterval(tick);tick=setInterval(render,250);}\ndocument.addEventListener('visibilitychange',()=>{cancelPending();stopSound();const current=renderSilently();if(document.hidden)say('页面进入后台，声景已停止；计时仍按截止时间计算。');else say(current.state==='finished'?'计时已在后台结束，未补播提示音。':'已补算当前计时；声音不会自动重播。')});\nwindow.addEventListener('pagehide',()=>{cancelPending();cueReady=false;if(tick!==null){clearInterval(tick);tick=null}stopSound();renderSilently();audio.close().catch(()=>{})});\nwindow.addEventListener('pageshow',event=>{if(!event.persisted)return;cancelPending();cueReady=false;audio=createPracticeAudio();audio.setVolume(Number($('volume').value)/100);audio.setMuted($('mute').getAttribute('aria-pressed')==='true');const current=renderSilently();startTick();say(current.state==='finished'?'计时已结束，缓存恢复后未补播提示音。':'页面已恢复，计时继续；声音保持关闭，请手动播放。')});\nview(location.pathname.endsWith('/sounds')?'sounds':'timer');config();render();startTick();\n","timer":"export function minutesValue(value){const n=typeof value==='string'&&value.trim()!==''?Number(value):value;if(!Number.isInteger(n)||n<1||n>180)throw new RangeError('请设置1至180分钟的整数时长');return n;}\nexport function createMeditationTimer(){\n let state='idle',duration=20*60000,preparation=10000,remaining=duration+preparation,deadline=null,interval=0;\n const validNow=now=>{if(!Number.isFinite(now))throw Error('INVALID_CLOCK');return now};\n function snapshot(now=Date.now()){validNow(now);if(state==='running'){remaining=Math.max(0,Math.min(duration+preparation,deadline-now));if(remaining===0){state='finished';deadline=null}}const meditationRemaining=Math.min(duration,remaining),preparing=remaining>duration;return{state,phase:state==='idle'?'ready':preparing?'preparation':state==='finished'?'finished':'meditation',remainingMs:remaining,phaseRemainingMs:state==='idle'?duration:preparing?remaining-duration:meditationRemaining,durationMs:duration,preparationMs:preparation,meditationElapsedMs:duration-meditationRemaining,intervalsCompleted:interval?Math.floor((duration-meditationRemaining)/interval):0,progress:(duration+preparation-remaining)/(duration+preparation)}}\n return {snapshot,configure({minutes=20,preparationSeconds=10,intervalMinutes=0}={}){if(state==='running'||state==='paused')throw Error('结束本次计时后再修改设置');const nextDuration=minutesValue(minutes)*60000;if(![0,10,30].includes(Number(preparationSeconds)))throw Error('INVALID_PREPARATION');const v=Number(intervalMinutes);if(!Number.isInteger(v)||v<0||v>180)throw Error('INVALID_INTERVAL');duration=nextDuration;preparation=Number(preparationSeconds)*1000;interval=v*60000;remaining=duration+preparation;state='idle';deadline=null;return snapshot()},start(now=Date.now()){validNow(now);if(!['idle','finished'].includes(state))throw Error('TIMER_ALREADY_ACTIVE');remaining=duration+preparation;deadline=now+remaining;state='running';return snapshot(now)},pause(now=Date.now()){const s=snapshot(now);if(s.state!=='running')return s;state='paused';deadline=null;return snapshot(now)},resume(now=Date.now()){validNow(now);if(state!=='paused')throw Error('TIMER_NOT_PAUSED');deadline=now+remaining;state='running';return snapshot(now)},finish(now=Date.now()){validNow(now);remaining=duration+preparation;deadline=null;state='idle';return snapshot(now)}};\n}\n","audio":"export function createPracticeAudio({createContext=()=>new (globalThis.AudioContext||globalThis.webkitAudioContext)(),random=Math.random,schedule=setTimeout,cancel=clearTimeout}={}){\n let context=null,master=null,current=[],all=new Set(),tasks=new Set(),generation=0,volume=.09,muted=false,closed=false;\n const track=node=>{all.add(node);return node};\n function cleanup(nodes){current=current.filter(n=>!nodes.includes(n));for(const n of nodes){try{n.stop?.()}catch{}try{n.disconnect()}catch{}all.delete(n)}}\n function ramp(gain,value,seconds=.08){const at=context.currentTime;gain.gain.cancelScheduledValues(at);gain.gain.setValueAtTime(gain.gain.value,at);gain.gain.linearRampToValueAtTime(value,at+seconds)}\n function after(fn,ms){let id=schedule(()=>{tasks.delete(id);fn()},ms);tasks.add(id)}\n async function ready(){if(closed)throw Error('音频会话已关闭');if(!context){context=createContext();master=track(context.createGain());master.gain.value=muted?0:volume*.12;master.connect(context.destination)}await context.resume();if(closed||context.state!=='running')throw Error('浏览器未允许播放，请再次点击开始声音');return context}\n function stop(){generation++;const nodes=current;current=[];for(const n of nodes)if(n._practiceFade)ramp(n,0);if(nodes.length)after(()=>cleanup(nodes),120)}\n function noise(kind){const buffer=context.createBuffer(1,Math.ceil(context.sampleRate*4),context.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){const white=random()*2-1;last=(last+.02*white)/1.02;data[i]=kind==='brown'?Math.max(-1,Math.min(1,last*3.5)):white*.35}const source=track(context.createBufferSource());source.buffer=buffer;source.loop=true;const filter=track(context.createBiquadFilter());filter.type='lowpass';filter.frequency.value=kind==='brown'?650:1800;const fade=track(context.createGain());fade.gain.value=0;fade._practiceFade=true;source.connect(filter);filter.connect(fade);fade.connect(master);ramp(fade,1,.25);source.start();current=[source,filter,fade]}\n function bell(){if(!context||closed||context.state!=='running')return false;const nodes=[];for(const [ratio,level]of [[1,.5],[2.756,.17],[5.404,.06]]){const osc=track(context.createOscillator()),gain=track(context.createGain()),at=context.currentTime;nodes.push(osc,gain);gain._practiceFade=true;osc.type='sine';osc.frequency.value=220*ratio;gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(level,at+.015);gain.gain.exponentialRampToValueAtTime(.0001,at+3.5);osc.connect(gain);gain.connect(master);osc.start();osc.stop(at+3.6)}current.push(...nodes);after(()=>cleanup(nodes),3700);return true}\n return {async prepare(){await ready();return true},async play(kind){if(!['brown','rain','bell'].includes(kind))throw Error('UNKNOWN_SOUND');stop();const request=++generation;await ready();if(closed||request!==generation)return false;if(kind==='bell')return bell();noise(kind);return true},bell,stop,setVolume(value){if(!Number.isFinite(value)||value<0||value>1)throw Error('INVALID_VOLUME');volume=value;if(master)ramp(master,muted?0:volume*.12)},setMuted(value){muted=!!value;if(master)ramp(master,muted?0:volume*.12)},status(){return{ready:context?.state==='running',playing:current.length>0,muted,volume,closed}},async close(){if(closed)return;closed=true;generation++;for(const task of tasks)cancel(task);tasks.clear();cleanup([...all]);current=[];master=null;if(context){await context.close();context=null}}};\n}\n"};
